import{_ as i,c as t,o as r,ae as n}from"./chunks/framework.Bw0Gm4PQ.js";const m=JSON.parse('{"title":"RESTORING AMERICA’S MARITIME DOMINANCE","description":"","frontmatter":{"title":"RESTORING AMERICA’S MARITIME DOMINANCE","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/04/restoring-americas-maritime-dominance/","publishDate":"2025-04-09T19:08:59-04:00"},"headers":[],"relativePath":"executive-orders/2025-04-09-restoring-americas-maritime-dominance.md","filePath":"executive-orders/2025-04-09-restoring-americas-maritime-dominance.md"}'),o={name:"executive-orders/2025-04-09-restoring-americas-maritime-dominance.md"};function a(s,e,l,c,d,p){return r(),t("div",null,e[0]||(e[0]=[n('<h1 id="restoring-america-s-maritime-dominance" tabindex="-1">RESTORING AMERICA’S MARITIME DOMINANCE <a class="header-anchor" href="#restoring-america-s-maritime-dominance" aria-label="Permalink to &quot;RESTORING AMERICA’S MARITIME DOMINANCE&quot;">​</a></h1><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/04/restoring-americas-maritime-dominance/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/04/restoring-americas-maritime-dominance/</a></p><p>Published: 2025-04-09T19:08:59-04:00</p><ul><li><p><strong>Context and Overview</strong></p><ul><li>The United States&#39; commercial shipbuilding capacity and maritime workforce have declined due to government neglect, impacting national security.</li><li>The U.S. constructs less than 1% of global commercial ships, while China produces about 50%.</li><li>A comprehensive approach is needed to address these issues, including federal funding, competitive vessel production, and workforce development.</li></ul></li><li><p><strong>Policy Directive</strong></p><ul><li>The U.S. aims to revitalize its maritime industries and workforce to enhance national security and economic prosperity.</li></ul></li><li><p><strong>Maritime Action Plan (MAP)</strong></p><ul><li>Due within 210 days, led by the Assistant to the President for National Security Affairs (APNSA) with several key department heads.</li><li>The Office of Management and Budget (OMB) will assess legislative, regulatory, and fiscal issues related to the MAP.</li><li>The MAP must comply with the Buy American Act and consider various sections of the order.</li></ul></li><li><p><strong>Assessment Actions</strong></p><ul><li>Within 180 days, the Secretary of Defense and others will assess options for using authorities and resources to invest in the Maritime Industrial Base, focusing on shipbuilding and supply chains.</li><li>Identify key components in the supply chain for prioritization and ensure public/private investments are based on clear metrics.</li></ul></li><li><p><strong>Trade and Tariffs</strong></p><ul><li>The USTR will gather information for actions from a Section 301 investigation on the PRC&#39;s maritime targeting, potentially proposing tariffs on certain equipment to address competition.</li></ul></li><li><p><strong>Foreign Cargo Regulations</strong></p><ul><li>To prevent evasion of the Harbor Maintenance Fee, the Secretary of Homeland Security will require foreign cargo to clear U.S. Customs at designated ports.</li></ul></li><li><p><strong>International Collaboration</strong></p><ul><li>Within 90 days, the USTR will engage with allies on potential actions taken under this order and develop a progress report.</li></ul></li><li><p><strong>Financial Incentives</strong></p><ul><li>The Secretary of Commerce will recommend incentives for foreign shipbuilders to partner with U.S. firms within 90 days.</li></ul></li><li><p><strong>Funding Proposal</strong></p><ul><li>A Maritime Security Trust Fund will be proposed by the OMB Director for reliable funding linked to tax revenue and other sources.</li></ul></li><li><p><strong>Workforce Development</strong></p><ul><li>A report will be submitted to address maritime workforce challenges, including credentialing and educational reforms, within 90 days.</li></ul></li><li><p><strong>Acquisition Strategies</strong></p><ul><li>A proposal to improve acquisition strategies for government vessels will be developed within 90 days, aimed at enhancing efficiency and reducing costs.</li></ul></li><li><p><strong>Regulatory Review</strong></p><ul><li>Within 30 days, a review of procurement regulations will be conducted to identify opportunities for deregulation and cost reduction.</li></ul></li><li><p><strong>Increased Vessel Availability</strong></p><ul><li>A legislative proposal for adequate commercial vessel availability for national security will be delivered within 180 days.</li></ul></li><li><p><strong>Arctic Strategy</strong></p><ul><li>A strategy for securing Arctic waterways will be developed within 90 days.</li></ul></li><li><p><strong>Interagency Coordination</strong></p><ul><li>All plans and reports will involve interagency coordination and comply with national directives.</li></ul></li><li><p><strong>Implementation and Legal Considerations</strong></p><ul><li>The order emphasizes compliance with laws and appropriations, stating it does not create enforceable rights against the U.S. entities.</li></ul></li></ul>',4)]))}const g=i(o,[["render",a]]);export{m as __pageData,g as default};
